mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM selection_batch batch
    JOIN batch_student_eligibility eligibility
      ON eligibility.batch_id = batch.id
     AND eligibility.student_id = #{studentId}
    WHERE batch.id = #{batchId}
      AND eligibility.eligibility_status = 'ELIGIBLE'
      AND batch.batch_status IN ('PUBLISHED', 'OPEN', 'PAUSED')
)

SELECT feature_vector_json
FROM student_feature
WHERE batch_id = #{batchId}
  AND student_id = #{studentId}
LIMIT 1

WITH scoped_rooms AS ( SELECT scope.room_id FROM batch_room_scope scope WHERE scope.batch_id = #{batchId} UNION SELECT room.id FROM batch_building_scope scope JOIN dormitory_floor floor ON floor.building_id = scope.building_id JOIN room ON room.floor_id = floor.id WHERE scope.batch_id = #{batchId} UNION SELECT bed.room_id FROM batch_bed_scope scope JOIN bed ON bed.id = scope.bed_id WHERE scope.batch_id = #{batchId} ), scoped_beds AS ( SELECT scope.bed_id FROM batch_bed_scope scope WHERE scope.batch_id = #{batchId} UNION SELECT bed.id FROM batch_room_scope scope JOIN bed ON bed.room_id = scope.room_id WHERE scope.batch_id = #{batchId} UNION SELECT bed.id FROM batch_building_scope scope JOIN dormitory_floor floor ON floor.building_id = scope.building_id JOIN room ON room.floor_id = floor.id JOIN bed ON bed.room_id = room.id WHERE scope.batch_id = #{batchId} ), resident_stats AS ( SELECT assignment.room_id, COUNT(*) AS active_resident_count, SUM(CASE WHEN assignment.bed_id IS NULL THEN 1 ELSE 0 END) AS unknown_bed_resident_count FROM scoped_rooms scoped JOIN room_assignment assignment ON assignment.room_id = scoped.room_id AND assignment.assignment_status = 'ACTIVE' GROUP BY assignment.room_id ), available_beds AS ( SELECT bed.room_id, COUNT(*) AS available_bed_count FROM scoped_beds scoped JOIN bed ON bed.id = scoped.bed_id AND bed.operational_status = 'ENABLED' LEFT JOIN room_assignment occupied ON occupied.room_id = bed.room_id AND occupied.assignment_status = 'ACTIVE' AND occupied.bed_id = bed.id WHERE occupied.id IS NULL GROUP BY bed.room_id ) SELECT room.id, room.room_number, room.room_type, room.capacity, room.gender_restriction, room.resident_scope, room.operational_status, room.state_version, floor.floor_number, building.id AS building_id, building.building_code, building.building_name, COALESCE(resident_stats.active_resident_count, 0) AS active_resident_count, COALESCE(resident_stats.unknown_bed_resident_count, 0) AS unknown_bed_resident_count, COALESCE(available_beds.available_bed_count, 0) AS available_bed_count FROM scoped_rooms scoped JOIN room ON room.id = scoped.room_id JOIN dormitory_floor floor ON floor.id = room.floor_id JOIN dormitory_building building ON building.id = floor.building_id JOIN active_batch_room_lock active_lock ON active_lock.batch_id = #{batchId} AND active_lock.room_id = room.id LEFT JOIN resident_stats ON resident_stats.room_id = room.id LEFT JOIN available_beds ON available_beds.room_id = room.id
WHERE room.id = #{roomId}
ORDER BY room.id

SELECT assignment.room_id, COALESCE(batch_feature.feature_vector_json, preference.feature_vector_json) AS feature_vector_json FROM room_assignment assignment LEFT JOIN student_feature batch_feature ON batch_feature.student_id = assignment.student_id AND batch_feature.batch_id = #{batchId} LEFT JOIN student_preference_profile preference ON preference.student_id = assignment.student_id WHERE assignment.assignment_status = 'ACTIVE' AND assignment.room_id IN
#{roomId}
AND COALESCE(batch_feature.feature_vector_json, preference.feature_vector_json) IS NOT NULL ORDER BY assignment.room_id, assignment.assigned_at, assignment.id

WITH scoped_beds AS ( SELECT scope.bed_id FROM batch_bed_scope scope WHERE scope.batch_id = #{batchId} UNION SELECT bed.id FROM batch_room_scope scope JOIN bed ON bed.room_id = scope.room_id WHERE scope.batch_id = #{batchId} UNION SELECT bed.id FROM batch_building_scope scope JOIN dormitory_floor floor ON floor.building_id = scope.building_id JOIN room ON room.floor_id = floor.id JOIN bed ON bed.room_id = room.id WHERE scope.batch_id = #{batchId} ) SELECT bed.room_id, bed.bed_type, COUNT(*) AS amount FROM scoped_beds scoped JOIN bed ON bed.id = scoped.bed_id AND bed.operational_status = 'ENABLED' LEFT JOIN room_assignment occupied ON occupied.room_id = bed.room_id AND occupied.assignment_status = 'ACTIVE' AND occupied.bed_id = bed.id WHERE occupied.id IS NULL AND bed.room_id IN
#{roomId}
GROUP BY bed.room_id, bed.bed_type
